/*
 * Apple Music (music.apple.com) 原生 Ceru v2 插件 —— 搜索用 Apple 官方，取链酷我兜底
 * 站点：https://music.apple.com（搜索 amp-api）/ 酷我 kuwo 兜底取链
 * 音质：128k / 320k / flac（酷我兜底通道可如实交付）
 *
 * 实测（2026-11-19）：
 *   搜索: music.apple.com 首页 → /assets/index~{hash}.js（旧 index-legacy~{hash}.js 已废弃）
 *         → bundle 里所有 eyJ… 三段式 JWT，解 payload 选 iss='AMPWebPlay' → Bearer token
 *         → GET amp-api.music.apple.com/v1/catalog/cn/search?term=&types=songs&limit=25&offset=
 *         → results.songs.data[].{id(adamId), attributes:{name, artistName, albumName,
 *           durationInMillis, artwork.url, previews[0].url}}
 *         无需登录/订阅，token 有效期约 70 天（缓存到插件变量，过期重取）
 *   取链（酷我兜底）: 用 Apple 的 title+artist → GET search.kuwo.cn/r.s?all={title} {artist}
 *         → abslist[] → 匹配（归一化 title+artist，多候选按 |DURATION-appleDur| 升序，时长容差宽松）
 *         → rid（去 MUSIC_ 前缀）→ 第三方 kuwo 兜底通道（官方 nmobi 实测可用但本插件不用；
 *         反盗 anti.s 不用；以下两条为当前可用）：
 *           128k: haitang musicapi.haitangw.net/music/kw.php?id={rid}&level=standard&type=mp3 → 302 真 mp3
 *           320k: haitang …&level=high&type=mp3 → 302 真 mp3（部分曲目 320 无版权/被拒，魔数校验回退）
 *           flac: cihedai music.nxinxz.com/kw.php?id={rid}&level=lossless&type=mp3 → 302 真 flac（fLaC 魔数）
 *         取链后 Range 0-255 魔数校验（ID3/0xFFEx→mp3，fLaC→flac），不过即回退下一档/如实失败
 *   酷我搜索参数关键（2026-11-19 实测）：r.s 默认参数只返回 KTV伴奏/翻唱（版权过滤差异），
 *         必须带 searchapi:2 等完整参数组才返回原唱（晴天：默认=0原唱，searchapi2=10原唱）。
 *   时长: 匹配候选用 |DURATION-appleDur| 升序（宽松，不硬拒）；截断版/试听版时长差大不误杀
 *
 * 已知限制（如实标注）：
 *   - Apple 官方无订阅只返回 30-90s 预览片段，不用于取链；取链一律酷我兜底。
 *   - 部分曲目 320k/无损在酷我侧无权限，魔数校验不过则回退低档（宁缺毋假，不返回坏链）。
 */
exports.manifest = {
  manifestVersion: 2,
  id: 'ceru.applemusic',
  name: 'Apple Music',
  version: '1.0.0',
  description: 'Apple Music 搜索 + 酷我兜底取链，音质 128k/320k/flac',
  author: 'hebijunge',
  engines: { hostApi: '^2.0.0', logicRuntime: 'ceru-js@1' },
  modules: { logic: { entry: 'logic.main' } },
  permissions: [{ key: 'network', name: 'network.request', reason: '搜索 Apple Music、取酷我兜底播放地址与歌词需要访问网络' }],
  contributes: {
    providers: [{
      id: 'ceru.applemusic',
      name: 'Apple Music',
      protocols: ['music.search@1', 'music.resolve@1', 'music.lyrics@1'],
      qualities: ['128k', '320k', 'flac'],
      connectionMode: 'none'
    }]
  }
};

